---
import { getLangFromUrl, useTranslations, getLocalizedPath, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
---

<section id="architecture" class="architecture-teaser">
  <div class="container">
    <div class="teaser-card">
      <div class="teaser-content">
        <span class="teaser-badge">Featured Architecture</span>
        <h2>{t('architecture').title}</h2>
        <p>{t('architecture').subtitle}</p>

        <a href={`${getLocalizedPath('/', lang)}projects/data-source-automator`} class="btn btn-primary">
          {t('cta').viewArchitecture}
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M5 12h14M12 5l7 7-7 7"/>
          </svg>
        </a>
      </div>
    </div>
  </div>
</section>

<style>
  .architecture-teaser {
    background: linear-gradient(to bottom, var(--bg-primary), var(--bg-secondary));
    position: relative;
    overflow: hidden;
  }

  .architecture-teaser::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: var(--glass-border);
  }

  .teaser-card {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-xl);
    padding: var(--space-2xl);
    position: relative;
    overflow: hidden;
  }

  .teaser-card::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle at center, var(--halo) 0%, transparent 70%);
    pointer-events: none;
  }

  .teaser-content {
    position: relative;
    z-index: 1;
    text-align: center;
  }

  .teaser-badge {
    display: inline-block;
    font-size: 0.6875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 0.375rem 0.75rem;
    background: var(--accent-surface);
    border: 1px solid var(--accent-primary);
    border-radius: var(--radius-full);
    color: var(--accent-text);
    margin-bottom: var(--space-md);
  }

  .teaser-content h2 {
    font-size: 1.75rem;
    margin-bottom: var(--space-sm);
  }

  .teaser-content p {
    color: var(--text-secondary);
    max-width: 500px;
    margin: 0 auto var(--space-lg);
  }

  .btn {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
  }

  @media (max-width: 768px) {
    .teaser-card {
      padding: var(--space-xl);
    }

    .teaser-content h2 {
      font-size: 1.5rem;
    }
  }
</style>

---
/**
 * Tres puertas de entrada al mismo trabajo.
 *
 * Existe para que el visitante se reconozca antes de leer nada técnico. La
 * tercera puerta es la que antes vivía sola en /business como si fuera otro
 * mercado: el trabajo es el mismo, lo que cambia es el vocabulario, así que
 * la landing pasa a ser la versión sin jerga de este perfil y no una web
 * paralela.
 */
import { getLangFromUrl, useTranslations, getLocalizedPath, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const audience = t('audience');
---

<section id="audience" class="audience">
  <div class="container">
    <div class="section-header">
      <h2>{audience.title}</h2>
      <p>{audience.subtitle}</p>
    </div>

    <ul class="audience-list">
      {
        audience.items.map((item) => (
          <li class="audience-card">
            <p class="audience-tag">
              <span class="audience-number">{item.n}</span>
              {item.tag}
            </p>
            <h3>{item.title}</h3>

            <div class="audience-block">
              <p class="audience-label">{audience.stuckLabel}</p>
              <p class="audience-text">{item.stuck}</p>
            </div>

            <div class="audience-block">
              <p class="audience-label">{audience.enterLabel}</p>
              <p class="audience-text">{item.enter}</p>
            </div>

            {item.link && (
              <a class="audience-link" href={getLocalizedPath(item.link, lang)}>
                {item.linkText} <span aria-hidden="true">&rarr;</span>
              </a>
            )}
          </li>
        ))
      }
    </ul>
  </div>
</section>

<style>
  .audience {
    background: var(--bg-secondary);
  }

  .audience-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-xl);
    list-style: none;
    margin: 0;
    padding: 0;
  }

  .audience-card {
    display: flex;
    flex-direction: column;
    padding: var(--space-lg);
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
  }

  .audience-tag {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    font-size: 0.6875rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-muted);
    margin-bottom: var(--space-sm);
  }

  .audience-number {
    color: var(--accent-text);
  }

  .audience-card h3 {
    font-size: 1.125rem;
    line-height: 1.35;
    margin-bottom: var(--space-md);
  }

  .audience-block + .audience-block {
    margin-top: var(--space-md);
  }

  .audience-label {
    font-size: 0.6875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-muted);
    margin-bottom: 0.25rem;
  }

  .audience-text {
    font-size: 0.9375rem;
    line-height: 1.6;
    color: var(--text-secondary);
  }

  .audience-link {
    margin-top: auto;
    padding-top: var(--space-lg);
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--accent-text);
    text-decoration: none;
  }

  .audience-link:hover {
    color: var(--text-primary);
  }
</style>

---
import { getLangFromUrl, useTranslations, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);

// CLEARBIT_PK solo esta definida en el entorno de produccion de Vercel, asi
// que en local y en cada despliegue de preview los logos no cargaban y salia
// el texto de reserva. La clave de logo.dev es publicable —empieza por pk_ y
// viaja en el HTML de la web publica, no es un secreto— de modo que aqui va
// como valor por defecto y los logos salen en todos los entornos. La variable
// de entorno sigue teniendo prioridad si algun dia hay que rotarla.
const logoToken = import.meta.env.CLEARBIT_PK ?? 'pk_ApbaFjDFQA6vHn9rXOmYGg';

// Gonvarri llego a traves de Sapira, pero el trabajo fue directo con ellos
// como parte del equipo, asi que va en este grupo y no en el de abajo.
// Kent y King's contrataron a Javier —Kent ademas fue donde se formo—, de
// modo que tambien son empleadores, no formacion.
const directClients = [
  { name: 'Simple KYC', domain: 'simplekyc.com' },
  { name: 'Sapira.ai', domain: 'sapira.ai' },
  { name: 'Hastings Direct', domain: 'hastingsdirect.com' },
  { name: 'NTT Data', domain: 'nttdata.com' },
  { name: 'Gonvarri', domain: 'gonvarri.com' },
  { name: "King's College London", domain: 'kcl.ac.uk' },
  { name: 'University of Kent', domain: 'kent.ac.uk' },
];

const indirectClients = [
  { name: 'American Express', domain: 'americanexpress.com' },
  { name: 'Westpac', domain: 'westpac.com.au' },
  { name: 'Telefonica', domain: 'telefonica.com' },
  { name: 'Tirea', domain: 'tirea.es' },
];

const getLogoUrl = (domain: string) => `https://img.logo.dev/${domain}?token=${logoToken}`;
---

<section class="clients">
  <div class="container">
    <div class="clients-group">
      <p class="clients-label">{t('clients').direct}</p>
      <div class="clients-logos">
        {directClients.map((client) => (
          <div class="client-logo" title={client.name}>
            <img
              src={getLogoUrl(client.domain)}
              alt={client.name}
              width="120"
              height="40"
              loading="lazy"
              onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
            />
            <span class="client-fallback">{client.name}</span>
          </div>
        ))}
      </div>
    </div>

    <div class="clients-group">
      <p class="clients-label">{t('clients').indirect}</p>
      <div class="clients-logos">
        {indirectClients.map((client) => (
          <div class="client-logo" title={client.name}>
            <img
              src={getLogoUrl(client.domain)}
              alt={client.name}
              width="120"
              height="40"
              loading="lazy"
              onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
            />
            <span class="client-fallback">{client.name}</span>
          </div>
        ))}
      </div>
    </div>
  </div>
</section>

<style>
  .clients {
    padding: var(--space-md) 0 var(--space-xl);
    border-bottom: 1px solid var(--border);
  }

  .clients-group {
    margin-bottom: var(--space-lg);
  }

  .clients-group:last-child {
    margin-bottom: 0;
  }

  .clients-label {
    text-align: center;
    font-size: 0.875rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: var(--space-md);
  }

  .clients-logos {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--space-xl);
  }

  .client-logo {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 40px;
    filter: grayscale(100%) brightness(0.8);
    opacity: 0.6;
    transition: all 0.3s ease;
  }

  .client-logo:hover {
    filter: grayscale(0%) brightness(1);
    opacity: 1;
  }

  .client-logo img {
    max-height: 40px;
    max-width: 120px;
    width: auto;
    object-fit: contain;
  }

  /* Cuando el logo no carga —falta el token de logo.dev, o el servicio no
     responde— este texto ocupa su sitio. Iba con fondo y esquinas
     redondeadas, o sea con la forma de un boton, y prometia un clic que no
     existe. Ahora se lee como lo que es: el nombre de la empresa. */
  .client-fallback {
    display: none;
    font-size: 0.9375rem;
    color: var(--text-muted);
    font-weight: 500;
    letter-spacing: 0.01em;
    white-space: nowrap;
  }

  @media (max-width: 768px) {
    .clients-logos {
      gap: var(--space-lg);
    }

    .client-logo img {
      max-height: 32px;
      max-width: 100px;
    }
  }
</style>

---
import { getLangFromUrl, useTranslations, type Language } from '../i18n';
import { social } from '../config';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);

// Calendly URL with styling parameters
const calendlyUrl = 'https://calendly.com/javiecija96/discovery-call?hide_landing_page_details=1&hide_gdpr_banner=1&primary_color=6366f1';
---

<section id="contact" class="contact">
  <div class="container">
    <div class="contact-wrapper">
      <div class="contact-info">
        <h2>{t('contact').title}</h2>
        <p class="subtitle">{t('contact').subtitle}</p>

        <div class="labs-badge">
          <span class="labs-title">{t('labs').title}</span>
          <span class="labs-subtitle">{t('labs').subtitle}</span>
        </div>

        <div class="connect-alternatives">
          <span>{t('contact').connectFirst}</span>
          <div class="connect-links">
            <a href={social.linkedin} target="_blank" rel="noopener" class="connect-link">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/>
              </svg>
              LinkedIn
            </a>
            <a href={`mailto:${social.email}`} class="email-link">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
                <polyline points="22,6 12,13 2,6"/>
              </svg>
              {social.email}
            </a>
          </div>
        </div>
      </div>

      <div class="calendly-container" id="calendly-container">
        <!-- Calendly inline widget - loaded lazily -->
        <div
          class="calendly-inline-widget"
          id="calendly-widget"
          data-url={calendlyUrl}
        ></div>

        <!-- Loading placeholder -->
        <div class="calendly-loading" id="calendly-loading">
          <span>Loading calendar...</span>
        </div>

        <!-- Fallback button for when embed doesn't load -->
        <noscript>
          <a href={calendlyUrl} target="_blank" rel="noopener" class="btn btn-primary btn-lg">
            {t('contact').bookCall}
          </a>
        </noscript>
      </div>
    </div>
  </div>
</section>

<script>
  // Lazy load Calendly when Contact section is visible
  let calendlyLoaded = false;

  function loadCalendly() {
    if (calendlyLoaded) return;
    calendlyLoaded = true;

    // Load CSS
    const css = document.createElement('link');
    css.rel = 'stylesheet';
    css.href = 'https://assets.calendly.com/assets/external/widget.css';
    document.head.appendChild(css);

    // Load JS
    const script = document.createElement('script');
    script.src = 'https://assets.calendly.com/assets/external/widget.js';
    script.async = true;
    script.onload = () => {
      // Hide loading indicator
      const loading = document.getElementById('calendly-loading');
      if (loading) loading.style.display = 'none';
    };
    document.head.appendChild(script);
  }

  // Use Intersection Observer to lazy load
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        loadCalendly();
        observer.disconnect();
      }
    });
  }, {
    rootMargin: '200px' // Start loading 200px before visible
  });

  const contactSection = document.getElementById('contact');
  if (contactSection) {
    observer.observe(contactSection);
  }

  // Also expose loadCalendly globally for nav button
  (window as any).loadCalendlyPopup = function(url: string) {
    if (!calendlyLoaded) {
      loadCalendly();
      // Wait for script to load then open popup
      const checkCalendly = setInterval(() => {
        if ((window as any).Calendly) {
          clearInterval(checkCalendly);
          (window as any).Calendly.initPopupWidget({ url });
        }
      }, 100);
    } else if ((window as any).Calendly) {
      (window as any).Calendly.initPopupWidget({ url });
    }
  };
</script>

<style>
  .contact {
    padding: var(--space-3xl) 0;
  }

  .contact-wrapper {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-3xl);
    align-items: start;
  }

  .contact-info h2 {
    margin-bottom: var(--space-md);
  }

  .contact-info .subtitle {
    font-size: 1.125rem;
    color: var(--text-secondary);
    margin-bottom: var(--space-xl);
  }

  .labs-badge {
    display: inline-flex;
    flex-direction: column;
    padding: var(--space-md) var(--space-lg);
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    margin-bottom: var(--space-xl);
  }

  .labs-title {
    font-size: 1.25rem;
    font-weight: 600;
    background: var(--accent-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .labs-subtitle {
    font-size: 0.875rem;
    color: var(--text-muted);
    font-style: italic;
  }

  .connect-alternatives {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
  }

  .connect-alternatives > span {
    font-size: 0.875rem;
    color: var(--text-muted);
  }

  .connect-links {
    display: flex;
    gap: var(--space-md);
  }

  .connect-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    font-size: 1rem;
    color: var(--accent-text);
    font-weight: 500;
    padding: var(--space-sm) var(--space-md);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    background: var(--bg-card);
    transition: all 0.2s ease;
  }

  .connect-link:hover {
    background: var(--accent-primary);
    color: white;
    border-color: var(--accent-primary);
  }

  .connect-link svg {
    flex-shrink: 0;
  }

  .email-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    font-size: 1rem;
    color: var(--accent-text);
    font-weight: 500;
  }

  .email-link:hover {
    text-decoration: underline;
  }

  .email-link svg {
    flex-shrink: 0;
    color: var(--text-muted);
  }

  .calendly-container {
    background: var(--bg-card);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    min-height: 630px;
  }

  .calendly-inline-widget {
    min-width: 100%;
    height: 630px;
  }

  .calendly-loading {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: var(--text-muted);
    font-size: 0.875rem;
  }

  .calendly-container {
    position: relative;
  }

  .btn-lg {
    display: block;
    text-align: center;
    padding: var(--space-md) var(--space-xl);
    margin: var(--space-xl);
  }

  @media (max-width: 768px) {
    .contact-wrapper {
      grid-template-columns: 1fr;
      gap: var(--space-xl);
    }

    .connect-links {
      flex-direction: column;
      align-items: flex-start;
      gap: var(--space-sm);
    }

    .calendly-container {
      min-height: 700px;
    }

    .calendly-inline-widget {
      height: 700px;
    }
  }
</style>

---
/**
 * Las objeciones que un cliente se hace y no dice en voz alta, contestadas
 * antes de la llamada. Van en <details> para que la sección se lea de un
 * vistazo y solo se abra lo que interesa.
 */
import { getLangFromUrl, useTranslations, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const faq = t('faq');
---

<section id="faq" class="faq">
  <div class="container">
    <div class="section-header">
      <h2>{faq.title}</h2>
      <p>{faq.subtitle}</p>
    </div>

    <div class="faq-list">
      {
        faq.items.map((item) => (
          <details class="faq-item">
            <summary>
              <span class="faq-question">{item.q}</span>
              <svg
                class="faq-chevron"
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
                aria-hidden="true"
              >
                <path d="m6 9 6 6 6-6" />
              </svg>
            </summary>
            <p class="faq-answer">{item.a}</p>
          </details>
        ))
      }
    </div>
  </div>
</section>

<style>
  .faq {
    background: var(--bg-secondary);
  }

  .faq-list {
    max-width: 760px;
    margin: 0 auto;
    border-top: 1px solid var(--border);
  }

  .faq-item {
    border-bottom: 1px solid var(--border);
  }

  .faq-item summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md);
    padding: var(--space-md) 0;
    cursor: pointer;
    list-style: none;
    color: var(--text-primary);
    transition: color var(--transition-fast);
  }

  /* El triángulo por defecto de Safari va aparte del ::marker */
  .faq-item summary::-webkit-details-marker {
    display: none;
  }

  .faq-item summary:hover {
    color: var(--accent-text);
  }

  .faq-item summary:focus-visible {
    outline: 2px solid var(--accent-text);
    outline-offset: 4px;
    border-radius: var(--radius-sm);
  }

  .faq-question {
    font-size: 1.0625rem;
    font-weight: 600;
    line-height: 1.4;
  }

  .faq-chevron {
    flex-shrink: 0;
    color: var(--text-muted);
    transition: transform var(--transition-base);
  }

  .faq-item[open] .faq-chevron {
    transform: rotate(180deg);
  }

  .faq-answer {
    padding: 0 var(--space-2xl) var(--space-lg) 0;
    color: var(--text-secondary);
    line-height: 1.7;
  }

  @media (max-width: 768px) {
    .faq-answer {
      padding-right: 0;
    }
  }
</style>

---
import { getLangFromUrl, useTranslations, getLocalizedPath, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
---

<section class="hero">
  <div class="container hero-container">
    <div class="hero-content">
      <p class="hero-eyebrow">{t('hero').role}</p>
      <h1 class="hero-title">{t('hero').subtitle}</h1>
      <p class="hero-lead">{t('hero').subheadline}</p>
