              <span class="phase-duration">{step.duration}</span>
            </div>
            <p class="phase-description">{step.description}</p>
            <p class="phase-deliverable">
              <span class="phase-deliverable-mark" aria-hidden="true">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                  <path d="M20 6 9 17l-5-5" />
                </svg>
              </span>
              {step.deliverable}
            </p>
          </div>
        </li>
      ))}
    </ol>

    <div class="principles">
      <h3 class="principles-title">{process.principlesTitle}</h3>
      <div class="principles-grid">
        {process.principles.map((principle) => (
          <div class="principle">
            <h4>{principle.title}</h4>
            <p>{principle.text}</p>
          </div>
        ))}
      </div>
    </div>
  </div>
</section>

<style>
  .process {
    background: var(--bg-secondary);
  }

  /* The phases read as a vertical spine: the rail carries the eye down and
     keeps each phase's deliverable next to the phase that produces it. */
  .phases {
    list-style: none;
    max-width: 780px;
    margin: 0 auto;
    padding: 0;
  }

  .phase {
    position: relative;
    display: grid;
    grid-template-columns: 48px 1fr;
    gap: var(--space-lg);
    padding-bottom: var(--space-xl);
  }

  .phase:last-child {
    padding-bottom: 0;
  }

  /* Rail segment between one marker and the next. */
  .phase:not(:last-child)::before {
    content: '';
    position: absolute;
    left: 23px;
    top: 48px;
    bottom: 8px;
    width: 2px;
    background: var(--border);
  }

  .phase-marker {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--border-strong);
    border-radius: 50%;
    background: var(--bg-card);
    position: relative;
    z-index: 1;
  }

  .phase-number {
    font-size: 0.8125rem;
    font-weight: 600;
    color: var(--accent-text);
  }

  .phase-body {
    padding-top: 0.375rem;
  }

  .phase-heading {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: var(--space-sm);
    margin-bottom: var(--space-xs);
  }

  .phase-heading h3 {
    font-size: 1.25rem;
    font-weight: 600;
  }

  .phase-duration {
    font-size: 0.75rem;
    color: var(--text-muted);
    padding: 0.125rem 0.5rem;
    border: 1px solid var(--border);
    border-radius: var(--radius-full);
    white-space: nowrap;
  }

  .phase-description {
    font-size: 0.9375rem;
    line-height: 1.65;
    margin-bottom: var(--space-sm);
  }

  .phase-deliverable {
    display: flex;
    align-items: flex-start;
    gap: var(--space-xs);
    font-size: 0.875rem;
    color: var(--text-primary);
  }

  .phase-deliverable-mark {
    color: var(--accent-text);
    flex-shrink: 0;
    line-height: 1;
    margin-top: 0.3125rem;
  }

  .principles {
    max-width: 980px;
    margin: var(--space-3xl) auto 0;
    padding-top: var(--space-xl);
    border-top: 1px solid var(--border);
  }

  .principles-title {
    font-size: 0.8125rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--text-muted);
    text-align: center;
    margin-bottom: var(--space-xl);
  }

  .principles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: var(--space-xl);
  }

  .principle h4 {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: var(--space-xs);
  }

  .principle p {
    font-size: 0.875rem;
    line-height: 1.65;
  }

  @media (max-width: 768px) {
    .phase {
      grid-template-columns: 40px 1fr;
      gap: var(--space-md);
    }

    .phase-marker {
      width: 40px;
      height: 40px;
    }

    .phase:not(:last-child)::before {
      left: 19px;
      top: 40px;
    }

    .phase-body {
      padding-top: 0.5rem;
    }

    .principles {
      margin-top: var(--space-2xl);
    }

    .principles-grid {
      gap: var(--space-lg);
    }
  }
</style>

---
import type { Project } from '../data/projects';
import { getLangFromUrl, useTranslations, getLocalizedPath, type Language } from '../i18n';
import MermaidDiagram from './MermaidDiagram.astro';
import TechStack from './TechStack.astro';

interface Props {
  project: Project;
}

const { project } = Astro.props;
const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);

// Category labels for display
const categoryLabels: Record<string, string> = {
  automation: lang === 'es' ? 'Automatización IA' : 'AI Automation',
  assistants: lang === 'es' ? 'Asistentes IA' : 'AI Assistants',
  mcp: 'MCP',
  domainSystems: lang === 'es' ? 'Sistemas de Dominio' : 'Domain Systems',
  products: lang === 'es' ? 'Productos' : 'Products'
};

const projectTranslations = t('projects')[project.key as keyof ReturnType<typeof t>['projects']];
const detailTranslations = t('projectDetails')[project.key as keyof ReturnType<typeof t>['projectDetails']];
---

<article class="project-detail">
  <header class="project-header">
    <a href={`${getLocalizedPath('/', lang)}#projects`} class="back-link">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
        <path d="M19 12H5M12 19l-7-7 7-7"/>
      </svg>
