  .outcomes-list {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  .outcomes-list li {
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm);
    font-size: 1rem;
