  .mcp-band:hover {
    background: var(--glass-border);
    color: inherit;
  }

  .mcp-inner {
    display: flex;
    align-items: center;
    gap: var(--space-md);
  }

  .mcp-icon {
    font-size: 1.5rem;
    flex-shrink: 0;
  }

  .mcp-content h4 {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 0.25rem;
  }

  .mcp-content p {
    font-size: 0.875rem;
    line-height: 1.5;
    color: var(--text-secondary);
    margin: 0;
  }

  @media (max-width: 768px) {
    .mcp-inner {
      flex-direction: column;
      text-align: center;
    }
  }
</style>

---
import { getLangFromUrl, useTranslations, type Language } from '../i18n';
import type { Skill } from '../data/skills';

interface Props {
  skill: Skill;
}

const { skill } = Astro.props;
const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const s = t('skills');
const badge = skill.visibility === 'public' ? s.badges.public : s.badges.internal;
const isLink = skill.visibility === 'public' && !!skill.repoUrl;
const Tag = isLink ? 'a' : 'div';
---

<Tag
  class:list={['card', 'skill-card', { 'is-link': isLink }]}
  {...isLink ? { href: skill.repoUrl, target: '_blank', rel: 'noopener' } : {}}
>
  <div class="skill-header">
    <span class="visibility-badge" data-visibility={skill.visibility}>{badge}</span>
