/**
 * Va en el <head>, antes de que se pinte nada.
 *
 * `is:inline` es deliberado: Astro no debe procesarlo ni moverlo a un
 * bundle diferido. Si el tema se aplicara después del primer pintado, quien
 * eligió claro vería un fogonazo oscuro en cada navegación.
 *
 * No lee prefers-color-scheme a propósito. El oscuro es el tema por defecto
 * de este sitio: solo se cambia si la persona lo pidió explícitamente.
 */
---

<script is:inline>
  try {
    if (localStorage.getItem('theme') === 'light') {
      document.documentElement.setAttribute('data-theme', 'light');
    }
  } catch {
    // Almacenamiento bloqueado: se queda en el tema por defecto.
  }
</script>

---
/**
 * Interruptor de tema. El oscuro es el de por defecto; el claro es opt-in y
 * se recuerda en localStorage.
 *
 * Los tres layouts tienen su propia cabecera duplicada, así que esto vive
 * aquí para no escribir el mismo botón tres veces y que se desincronicen.
 */
import { getLangFromUrl, type Language } from '../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const label = lang === 'es' ? 'Cambiar tema' : 'Toggle theme';
---

<button class="theme-toggle" type="button" aria-label={label} title={label} aria-pressed="false">
  <svg class="icon-sun" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true">
    <circle cx="12" cy="12" r="4" />
    <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />
  </svg>
  <svg class="icon-moon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
    <path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z" />
  </svg>
</button>

<style>
  .theme-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    padding: 0;
    background: transparent;
    border: 1px solid var(--border);
    border-radius: var(--radius-full);
    color: var(--text-secondary);
    cursor: pointer;
    transition:
      color var(--transition-fast),
      border-color var(--transition-fast);
  }

  .theme-toggle:hover {
    color: var(--text-primary);
    border-color: var(--border-strong);
  }

  .theme-toggle:focus-visible {
    outline: 2px solid var(--accent-text);
    outline-offset: 2px;
  }

  /* Se enseña el destino, no el estado: en oscuro el sol, porque pulsar
     lleva al claro. */
  .icon-moon {
    display: none;
  }

  :global(:root[data-theme='light']) .icon-sun {
    display: none;
  }

  :global(:root[data-theme='light']) .icon-moon {
    display: block;
  }
</style>

<script>
  const KEY = 'theme';
  const root = document.documentElement;

  const sync = () => {
    const light = root.getAttribute('data-theme') === 'light';
    document
      .querySelectorAll('.theme-toggle')
      .forEach((b) => b.setAttribute('aria-pressed', String(light)));
  };

  document.querySelectorAll('.theme-toggle').forEach((btn) => {
    btn.addEventListener('click', () => {
      const light = root.getAttribute('data-theme') === 'light';
      if (light) root.removeAttribute('data-theme');
      else root.setAttribute('data-theme', 'light');

      try {
        localStorage.setItem(KEY, light ? 'dark' : 'light');
      } catch {
        // Modo privado o cookies bloqueadas: el tema vale para esta página
        // y no se recuerda. Preferible a romper el botón.
      }
      sync();
    });
  });

  sync();
</script>

