// Everything the client script needs, so it never has to reach back into i18n.
const clientData = {
  questions,
  levelNames: a.ui.levelNames,
  verdicts: a.result.verdicts,
  lang,
  // Turns the score into something specific: which gap to close first, and why.
  detail: {
    priority: a.result.priority,
    why: a.result.why,
    startHere: a.result.startHere,
    harmPattern: a.result.harmPattern,
    harmCategories: a.result.harmCategories,
    spreadPattern: a.result.spreadPattern
  },
  labels: {
    of: a.ui.of,
    unknownLabel: a.result.unknownLabel,
    unknownLabelOne: a.result.unknownLabelOne,
    emptyBoxes: a.result.emptyBoxes,
    send: a.result.send,
