      </div>
    </div>
  </div>
</section>

<script is:inline define:vars={{ clientData }}>
  (() => {
    const { questions, levelNames, verdicts, labels, lang, detail } = clientData;
    let lastResult = { text: '', unknown: 0, headline: '' };
    const answers = new Array(questions.length).fill(null);
    const order = new Array(questions.length).fill(null);
    let current = 0;

    const $ = (id) => document.getElementById(id);
    const intro = $('intro');
    const quiz = $('quiz');
    const result = $('result');

    function show(panel) {
      [intro, quiz, result].forEach((p) => p.classList.add('hidden'));
      panel.classList.remove('hidden');
    }

    function renderQuestion() {
      const q = questions[current];
      $('q-category').textContent = q.category;
      $('q-prompt').textContent = q.prompt;
      $('progress-text').textContent = `${current + 1} ${labels.of} ${questions.length}`;
      $('progress-fill').style.width = `${(current / questions.length) * 100}%`;
      $('back').style.visibility = current === 0 ? 'hidden' : 'visible';

      const box = $('options');
      box.innerHTML = '';
      // Shuffled once per question and remembered, so going back doesn't
      // reshuffle under the reader. Order is what would otherwise give the
      // "right" answer away.
      if (!order[current]) {
        const idx = q.options.map((_, i) => i);
        for (let i = idx.length - 1; i > 0; i -= 1) {
          const j = Math.floor(Math.random() * (i + 1));
          [idx[i], idx[j]] = [idx[j], idx[i]];
        }
        order[current] = idx;
      }

      order[current].forEach((optionIndex) => {
        const option = q.options[optionIndex];
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'option' + (answers[current] === option.level ? ' selected' : '');
        btn.textContent = option.text;
        btn.addEventListener('click', () => {
          answers[current] = option.level;
          if (current < questions.length - 1) {
            current += 1;
            renderQuestion();
          } else {
            renderResult();
          }
        });
        box.appendChild(btn);
      });
    }

    function renderResult() {
      show(result);

      const scored = questions.map((q, i) => ({ category: q.category, level: answers[i] ?? 0 }));
      const count = scored.filter((row) => row.level === 0).length;
      const verdict =
        count === 0 ? verdicts.none : count <= 2 ? verdicts.few : count <= 4 ? verdicts.some : verdicts.many;

      // Name the single gap worth closing first, ranked by who pays when it
      // fails rather than by the order the questions happened to come in.
      const weakest = Math.min(...scored.map((row) => row.level));
      const candidates = scored.filter((row) => row.level === weakest).map((row) => row.category);
      const first = detail.priority.find((category) => candidates.includes(category));

      const parts = [];
      const noun = count === 1 ? labels.unknownLabelOne : labels.unknownLabel;
      parts.push(count > 0 ? `${count} ${noun}. ${verdict}` : verdict);

      if (first && weakest < 3) {
        parts.push(detail.startHere.replace('{name}', first).replace('{why}', detail.why[first]));
      }

      // Two patterns worth calling out beyond the count itself.
      const harmGaps = scored.filter(
        (row) => row.level <= 1 && detail.harmCategories.includes(row.category)
      ).length;
      if (harmGaps >= 2) {
        parts.push(detail.harmPattern);
      } else if (weakest === 0 && Math.max(...scored.map((row) => row.level)) === 3) {
        parts.push(detail.spreadPattern);
      }

      const headline = parts.join(' ');
      $('verdict').textContent = headline;

      // The map: every category with the level chosen, unknowns first so the
      // gaps are what you read, not what you have to hunt for.
      const rows = questions
        .map((q, i) => ({ category: q.category, level: answers[i] ?? 0 }))
        .sort((a, b) => a.level - b.level);

      const map = $('map');
      map.innerHTML = '';
      rows.forEach((row) => {
        const el = document.createElement('div');
        el.className = 'map-row' + (row.level === 0 ? ' empty' : '');

        const name = document.createElement('span');
        name.className = 'map-category';
        name.textContent = row.category;

        const meter = document.createElement('span');
        meter.className = 'map-meter';
        for (let s = 1; s <= 3; s += 1) {
          const seg = document.createElement('span');
          seg.className = 'seg' + (row.level >= s ? ' filled' : '');
          meter.appendChild(seg);
        }

        const label = document.createElement('span');
        label.className = 'map-level';
        label.textContent = levelNames[row.level];

        el.append(name, meter, label);
