const situations = t('mentoring').situations;

interface Case {
  name: string;
  body: string;
}
---

<section class="mentoring-situations">
  <div class="container">
    <h2>{situations.title}</h2>

    <div class="cases">
      {situations.cases.map((item: Case) => (
        <article class="case">
          <h3>{item.name}</h3>
          <p>{item.body}</p>
        </article>
      ))}
    </div>

    <p class="closing">{situations.closing}</p>
  </div>
</section>

<style>
  .mentoring-situations {
    padding: var(--space-2xl) 0;
    background: var(--surface-subtle);
  }

  h2 {
    font-size: clamp(1.5rem, 2.5vw, 2rem);
    text-align: center;
    margin-bottom: var(--space-xl);
  }

  /* Flex rather than grid: with an odd number of cases the last one wraps to a
     row of its own, and grid would pin it to the left. Centring the leftover is
     the whole reason for the choice. */
  .cases {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-lg);
    max-width: 940px;
    margin: 0 auto;
  }

  .case {
    flex: 1 1 300px;
    max-width: 440px;
    padding: var(--space-lg);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
  }

  .case h3 {
    font-size: 1.125rem;
    color: var(--accent-text);
    margin-bottom: var(--space-sm);
  }

  .case p {
    color: var(--text-secondary);
    line-height: 1.7;
  }

  .closing {
    max-width: 720px;
    margin: var(--space-xl) auto 0;
    text-align: center;
    color: var(--text-primary);
    font-size: 1.0625rem;
    line-height: 1.7;
  }
</style>

---
import { getLangFromUrl, useTranslations, type Language } from '../../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const system = t('mentoring').system;

// The diagrams are the ones published with the article; Spanish has its own set.
const suffix = lang === 'es' ? '-es' : '';
const loopImage = `/blog/what-you-still-need-to-know-to-ship${suffix}.png`;
const mapImage = `/blog/what-you-still-need-to-know-map${suffix}.png`;
const articleUrl = `/${lang}/blog/what-you-still-need-to-know-to-ship`;
const assessmentUrl = `/${lang}/assessment`;
---

<section class="mentoring-system">
  <div class="container">
    <div class="section-header">
      <h2>{system.title}</h2>
      <p>{system.subtitle}</p>
    </div>

    <div class="pieces">
      <article class="piece">
        <h3>{system.loopTitle}</h3>
        <p>{system.loopBody}</p>
        <img src={loopImage} alt={system.loopTitle} loading="lazy" />
      </article>

      <article class="piece">
        <h3>{system.mapTitle}</h3>
        <p>{system.mapBody}</p>
        <img src={mapImage} alt={system.mapTitle} loading="lazy" />
      </article>
    </div>

    <div class="read-more">
      <a href={articleUrl} class="btn btn-secondary">{system.readMore}</a>
      <a href={assessmentUrl} class="assessment-cta">{system.assessmentCta}</a>
    </div>
  </div>
</section>

<style>
  .mentoring-system {
    padding: var(--space-2xl) 0;
    background: var(--surface-subtle);
  }

  .section-header {
    max-width: 720px;
    margin: 0 auto var(--space-2xl);
    text-align: center;
  }

  .section-header h2 {
    font-size: clamp(1.75rem, 3vw, 2.5rem);
    margin-bottom: var(--space-sm);
  }

  .section-header p {
    color: var(--text-secondary);
    font-size: 1.0625rem;
  }

  .pieces {
    display: grid;
    gap: var(--space-2xl);
    max-width: 1000px;
    margin: 0 auto;
  }

  .piece h3 {
    font-size: 1.375rem;
    margin-bottom: var(--space-sm);
  }

  .piece p {
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: var(--space-lg);
    max-width: 720px;
  }

  .piece img {
    width: 100%;
    height: auto;
    border-radius: var(--radius-md);
    border: 1px solid var(--glass-border);
    display: block;
  }

  .read-more {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-md);
    margin-top: var(--space-2xl);
  }

  .assessment-cta {
    color: var(--accent-text);
    text-decoration: none;
    font-weight: 500;
  }

  .assessment-cta:hover {
    text-decoration: underline;
  }
</style>

---
import { getLangFromUrl, useTranslations, type Language } from '../../i18n';

const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const w = t('workshop');
const mentoringUrl = `/${lang}/mentoring`;

interface Named {
  name: string;
  body: string;
}

// The "what I need from you" items carry **bold** lead-ins; render them without
// pulling in a markdown dependency for three strings.
function withBold(value: string): string {
  return value.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
}
---

<section class="workshop">
  <div class="container">
    <header class="page-head">
      <h1>{w.hero.title}</h1>
      <p class="lead">{w.hero.subtitle}</p>
    </header>

    <div class="prose">
      <h2>{w.intro.title}</h2>
      {w.intro.body.map((p: string) => <p>{p}</p>)}
    </div>

    <h2 class="section-title">{w.day.title}</h2>
    <ol class="blocks">
      {w.day.blocks.map((block: Named) => (
        <li>
          <h3>{block.name}</h3>
          <p>{block.body}</p>
        </li>
      ))}
    </ol>

    <h2 class="section-title">{w.rules.title}</h2>
    <div class="rules">
      {w.rules.items.map((rule: Named) => (
        <article class="rule">
          <h3>{rule.name}</h3>
          <p>{rule.body}</p>
        </article>
      ))}
    </div>

    <div class="two-up">
      <section class="panel">
        <h2>{w.youget.title}</h2>
        <p class="panel-lead">{w.youget.body}</p>
        <ul>
          {w.youget.items.map((item: string) => <li>{item}</li>)}
        </ul>
      </section>

      <section class="panel">
        <h2>{w.need.title}</h2>
        <ul>
          {w.need.items.map((item: string) => <li set:html={withBold(item)} />)}
        </ul>
      </section>
    </div>

    <div class="prose after">
      <h2>{w.after.title}</h2>
      <p>{w.after.body}</p>
    </div>

    <div class="cta">
      <h2>{w.cta.title}</h2>
      <p>{w.cta.body}</p>
      <div class="cta-actions">
        <a href="#" onclick="Calendly.initPopupWidget({url: 'https://calendly.com/javiecija96/discovery-call?hide_landing_page_details=1&hide_gdpr_banner=1&primary_color=6366f1'});return false;" class="btn btn-primary btn-large">
          {w.cta.button}
        </a>
        <a href={mentoringUrl} class="btn btn-secondary">{w.cta.back}</a>
      </div>
    </div>
  </div>
</section>

<style>
  .workshop {
    padding-top: 120px;
    padding-bottom: var(--space-2xl);
  }

  .page-head {
    max-width: 760px;
    margin: 0 auto var(--space-2xl);
    text-align: center;
  }

  h1 {
    font-size: clamp(2.25rem, 4.5vw, 3.5rem);
    margin-bottom: var(--space-md);
    background: var(--accent-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.2;
  }

  .lead {
    color: var(--text-secondary);
    font-size: clamp(1.0625rem, 1.6vw, 1.25rem);
    line-height: 1.6;
  }

  .prose {
    max-width: 720px;
    margin: 0 auto var(--space-2xl);
  }

  .prose p {
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: var(--space-md);
  }

  .section-title {
    max-width: 720px;
    margin: 0 auto var(--space-lg);
    font-size: clamp(1.5rem, 2.5vw, 2rem);
  }

  .prose h2 {
    font-size: clamp(1.5rem, 2.5vw, 2rem);
    margin-bottom: var(--space-md);
  }

  /* The day, as a numbered sequence — the order is the content. */
  .blocks {
    max-width: 720px;
    margin: 0 auto var(--space-2xl);
    padding: 0;
    list-style: none;
    counter-reset: block;
    display: grid;
    gap: var(--space-lg);
  }

  .blocks li {
    counter-increment: block;
    padding-left: 3rem;
    position: relative;
  }

  .blocks li::before {
    content: counter(block);
    position: absolute;
    left: 0;
    top: 0;
    width: 2rem;
    height: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--accent-primary);
    border-radius: 50%;
    color: var(--accent-text);
    font-size: 0.875rem;
    font-weight: 600;
  }

  .blocks h3 {
    font-size: 1.125rem;
    margin-bottom: var(--space-xs);
  }

  .blocks p {
    color: var(--text-secondary);
    line-height: 1.7;
  }

  .rules {
    display: grid;
    gap: var(--space-md);
    max-width: 900px;
    margin: 0 auto var(--space-2xl);
  }

  .rule {
    padding: var(--space-lg);
    border: 1px solid var(--glass-border);
    border-left: 3px solid var(--accent-primary);
    border-radius: var(--radius-md);
  }

  .rule h3 {
    font-size: 1.0625rem;
    margin-bottom: var(--space-xs);
  }

  .rule p {
    color: var(--text-secondary);
    line-height: 1.7;
  }

  .two-up {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-lg);
    max-width: 900px;
    margin: 0 auto var(--space-2xl);
  }

  .panel {
    padding: var(--space-lg);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
  }

  .panel h2 {
    font-size: 1.25rem;
    margin-bottom: var(--space-sm);
  }

  .panel-lead {
    color: var(--text-muted);
    margin-bottom: var(--space-md);
  }

  .panel ul {
    margin: 0;
    padding-left: 1.1rem;
    display: grid;
    gap: var(--space-sm);
  }

  .panel li {
    color: var(--text-secondary);
    line-height: 1.6;
  }

  .after {
    margin-bottom: var(--space-2xl);
  }

  .cta {
    max-width: 640px;
    margin: 0 auto;
    text-align: center;
  }

  .cta h2 {
    font-size: clamp(1.5rem, 2.5vw, 2rem);
    margin-bottom: var(--space-sm);
  }

  .cta p {
    color: var(--text-secondary);
    line-height: 1.6;
    margin-bottom: var(--space-xl);
  }

  .cta-actions {
    display: flex;
    gap: var(--space-md);
    justify-content: center;
    flex-wrap: wrap;
  }

  .btn-large {
    padding: 1rem 2.5rem;
    font-size: 1.125rem;
  }
</style>

---
import { Image } from 'astro:assets';
import { getLangFromUrl, useTranslations, getLocalizedPath, type Language } from '../../i18n';
import { getEdition, getStoreLinks, type Book } from '../../data/publications';

interface Props {
  book: Book;
}

const { book } = Astro.props;
const lang = getLangFromUrl(Astro.url) as Language;
const t = useTranslations(lang);
const p = t('publications');

const edition = getEdition(book, lang);
const links = edition ? getStoreLinks(edition, lang) : { primary: null, secondary: null };
const articleHref = book.relatedArticle
  ? `${getLocalizedPath('/blog/', lang)}${book.relatedArticle}/`
  : null;
---

{edition && (
  <article class="card book-card">
    <div class="book-cover">
      <Image src={edition.cover} alt={edition.title} width={320} densities={[1, 2]} loading="lazy" />
    </div>
    <div class="book-body">
      <h3>{edition.title}</h3>
      <p class="blurb">{p.bookItems[book.key].blurb}</p>
      <div class="book-actions">
        {links.primary && (
          <a href={links.primary.href} target="_blank" rel="noopener" class="btn btn-primary">
            {links.primary.store === 'payhip' ? p.stores.payhip : p.stores.amazon}
          </a>
        )}
        {links.secondary && (
          <a href={links.secondary.href} target="_blank" rel="noopener" class="secondary-store">
            {p.stores.alsoAmazon}
          </a>
        )}
      </div>
      {articleHref && <a href={articleHref} class="related-article">{p.books.readArticle}</a>}
    </div>
  </article>
)}

<style>
  .book-card {
    display: grid;
    grid-template-columns: 320px 1fr;
    gap: var(--space-lg);
    align-items: start;
  }
  .book-cover img {
    width: 100%;
    height: auto;
    border-radius: var(--radius-md);
    display: block;
  }
  .book-body h3 {
    font-size: 1.375rem;
    margin-bottom: var(--space-sm);
  }
  .blurb {
    color: var(--text-secondary);
    line-height: 1.6;
    margin-bottom: var(--space-md);
  }
  .book-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-md);
  }
  .secondary-store {
    color: var(--text-muted);
    font-size: 0.9375rem;
    text-decoration: none;
    transition: color var(--transition-base);
  }
  .secondary-store:hover {
    color: var(--accent-text);
  }
  .related-article {
    display: inline-block;
    margin-top: var(--space-md);
    color: var(--text-muted);
    font-size: 0.9375rem;
    text-decoration: none;
    transition: color var(--transition-base);
  }
  .related-article:hover {
    color: var(--accent-text);
  }

  @media (max-width: 768px) {
    .book-card {
      grid-template-columns: 1fr;
    }
    .book-cover {
      max-width: 220px;
      margin: 0 auto;
    }
    .book-actions {
      flex-direction: column;
      align-items: stretch;
    }
  }
</style>

