              {project.liveUrl && (
                <a href={project.liveUrl} target="_blank" rel="noopener" class="btn btn-secondary btn-sm">
                  {t('projectDetails').viewLive}
                </a>
              )}
              {project.github && (
                <a href={project.github} target="_blank" rel="noopener" class="btn btn-secondary btn-sm">
                  GitHub
                </a>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  </section>
</Layout>

<script>
  const params = new URLSearchParams(window.location.search);
  const category = params.get('category');
  const buttons = document.querySelectorAll('.filter-btn');
  const cards = document.querySelectorAll('.project-card');

  function filter(cat) {
    cards.forEach(card => {
      card.style.display = (!cat || cat === 'all' || card.dataset.projectCategory === cat) ? '' : 'none';
    });
    buttons.forEach(btn => {
      btn.classList.toggle('active', btn.dataset.filter === (cat || 'all'));
    });
  }

  buttons.forEach(btn => {
    btn.addEventListener('click', () => {
      const f = btn.dataset.filter;
      filter(f);
      const url = new URL(window.location);
      if (f === 'all') url.searchParams.delete('category');
      else url.searchParams.set('category', f);
      history.replaceState(null, '', url);
    });
  });

  if (category) filter(category);
</script>

